'use client';
import {useState} from 'react'; import {Book} from '@/data/books'; import {SpreadArt} from './book-art';
export function Viewer({book}:{book:Book}){const [index,setIndex]=useState(0);const page=book.spreads[index]; const change=(n:number)=>setIndex((index+n+book.spreads.length)%book.spreads.length);return <section className="viewer" aria-label="Sample page viewer"><div className="viewer-book"><div className="viewer-copy"><span>Chapter {index+1}</span><p>“{page.quote}”</p></div><SpreadArt art={page.art}/></div><div className="viewer-controls"><button onClick={()=>change(-1)} aria-label="Previous sample page">← Previous</button><span>{index+1} / {book.spreads.length}</span><button onClick={()=>change(1)} aria-label="Next sample page">Next →</button></div></section>}
